import java.util.Scanner;

public class Main {
    static long n;
    static long[] A = new long[20];
    static long[] B = new long[20];
    static long ans;

    static void explore(int pos, long current, long cost) {
        if (cost >= ans) return;
        if (pos == 0) {
            if (current == 0) ans = cost;
            return;
        }
        long t = current / A[pos];
        long delta_neg = Math.abs(t) - 1;
        if (t < 0) delta_neg = -delta_neg;
        long delta_pos = Math.abs(t) + 1;
        if (t < 0) delta_pos = -delta_pos;

        explore(pos - 1, current - t * B[pos], cost + Math.abs(t) * pos);
        explore(pos - 1, current - delta_neg * B[pos], cost + Math.abs(delta_neg) * pos);
        explore(pos - 1, current - delta_pos * B[pos], cost + Math.abs(delta_pos) * pos);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 16; i++) B[i] = B[i - 1] * 10 + 1;
        A[1] = 1;
        for (int i = 2; i <= 16; i++) A[i] = A[i - 1] * 10;
        n = sc.nextLong();
        long temp = n;
        int digits = 0;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        ans = Long.MAX_VALUE;
        explore(digits, n, 0);
        explore(digits, B[digits + 1] - n, digits + 1);
        System.out.println(ans);
        sc.close();
    }
}
